// PublicUserClient provides type-safe operations for the users table.
type PublicUserClient interface {
	// --- Read Operations ---

	// Get returns a single publicUser by primary key.
	Get(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[PublicUserFieldOptions])) (*PublicUser, error)

	// GetMany returns users matching the given filter, field selection, and sort criteria.
	// When FieldOptions includes O2M or M2M relationships, they are loaded via an
	// errgroup fan-out — in parallel over the pool, and serialized by the
	// transaction's connection reservation when ctx carries one.
	GetMany(ctx context.Context, input *GetPublicUsersInput, opts ...func(*CallOptions[PublicUserFieldOptions])) ([]*PublicUser, error)

	// Exists returns true if a publicUser with the given primary key exists.
	Exists(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[PublicUserFieldOptions])) (bool, error)

	// ExistsWhere returns true if any publicUser matches the given filter.
	ExistsWhere(ctx context.Context, filter *PublicUserFilter, opts ...func(*CallOptions[PublicUserFieldOptions])) (bool, error)

	// Count returns the number of users matching the given filter.
	Count(ctx context.Context, filter *PublicUserFilter, opts ...func(*CallOptions[PublicUserFieldOptions])) (int64, error)

	// --- Write Operations ---

	// Create inserts a new publicUser and returns the created entity.
	Create(ctx context.Context, input *CreatePublicUserInput, opts ...func(*CallOptions[PublicUserFieldOptions])) (*PublicUser, error)

	// CreateMany inserts multiple users in batches and returns all created entities.
	// Sub-batches are not automatically rolled back on failure — wrap in a transaction for atomicity.
	CreateMany(ctx context.Context, inputs []*CreatePublicUserInput, opts ...func(*CallOptions[PublicUserFieldOptions])) ([]*PublicUser, error)

	// Update partially updates a publicUser by primary key and returns the updated entity.
	// Only fields where IsSet() is true are included in the SET clause.
	// Returns ErrNotFound if the primary key does not exist.
	Update(ctx context.Context, id uuid.UUID, input *UpdatePublicUserInput, opts ...func(*CallOptions[PublicUserFieldOptions])) (*PublicUser, error)

	// UpdateMany updates multiple users and returns the updated entities.
	UpdateMany(ctx context.Context, items []UpdatePublicUserItem, opts ...func(*CallOptions[PublicUserFieldOptions])) ([]*PublicUser, error)

	// UpdateWhere updates all users matching the filter and returns the updated entities.
	// Idempotent — returns empty slice when no rows match.
	UpdateWhere(ctx context.Context, filter *PublicUserFilter, input *UpdatePublicUserInput, opts ...func(*CallOptions[PublicUserFieldOptions])) ([]*PublicUser, error)

	// Upsert inserts a publicUser or updates it on conflict and returns the resulting entity.
	Upsert(ctx context.Context, input *CreatePublicUserInput, target PublicUserConflictTarget, opts ...func(*CallOptions[PublicUserFieldOptions])) (*PublicUser, error)

	// UpsertMany inserts or updates multiple users in batches and returns all resulting entities.
	// Inputs resolving to the same conflict target are deduped, last occurrence wins.
	UpsertMany(ctx context.Context, inputs []*CreatePublicUserInput, target PublicUserConflictTarget, opts ...func(*CallOptions[PublicUserFieldOptions])) ([]*PublicUser, error)

	// --- Hard Delete Operations ---

	// HardDelete permanently removes a publicUser from the database.
	// Idempotent — returns nil if the primary key does not exist.
	HardDelete(ctx context.Context, id uuid.UUID, opts ...func(*CallOptions[PublicUserFieldOptions])) error

	// HardDeleteMany permanently removes multiple users from the database.
	HardDeleteMany(ctx context.Context, ids []uuid.UUID, opts ...func(*CallOptions[PublicUserFieldOptions])) error

	// HardDeleteWhere permanently removes all users matching the filter.
	// Idempotent — returns nil when no rows match.
	HardDeleteWhere(ctx context.Context, filter *PublicUserFilter, opts ...func(*CallOptions[PublicUserFieldOptions])) error

	// --- Pagination Operations ---

	// Paginate returns a page of users with total count for offset-based pagination.
	Paginate(ctx context.Context, input PaginateInput[PublicUserFilter], opts ...func(*CallOptions[PublicUserFieldOptions])) (*PaginateResult[PublicUser], error)

	// Connection returns a Relay-style cursor-paginated connection of users.
	// Sort order is determined by cursor_keys — custom sorts are not supported.
	// Use Paginate for custom sort orders.
	Connection(ctx context.Context, input ConnectionInput[PublicUserFilter], opts ...func(*CallOptions[PublicUserFieldOptions])) (*Connection[PublicUser], error)

	// Stream returns an iterator over users matching the filter and sort criteria.
	// Rows are yielded as the driver returns them; cache is bypassed.
	// Stream cannot load relationships.
	//
	// Stream refuses an active transaction unless CallOptions.AllowInTransaction
	// is set, and the opt-in commits the caller to issuing nothing else on that
	// txCtx: the one rule that remains the caller's — drain or close a result set
	// before issuing the next statement on that txCtx — applied to a loop whose
	// body is caller code.
	Stream(ctx context.Context, input *StreamPublicUsersInput, opts ...func(*CallOptions[StreamPublicUserFieldOptions])) iter.Seq2[*PublicUser, error]
}

